import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int A = (int) st.nval;
        st.nextToken();
        int B = (int) st.nval;

        long[] sa = new long[A];
        for (int i = 0; i < A; i++) {
            st.nextToken();
            sa[i] = (long) st.nval;
        }

        int j = 0;
        for (int i = 0; i < B; i++) {
            st.nextToken();
            long y = (long) st.nval;
            while (j < A && sa[j] != y) j++;
            if (j == A) {
                System.out.println('N');
                return;
            }
            j++;
        }
        System.out.println('S');
    }
}
